#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float brush_radius;     // px radius (1..8)
    float detail;           // 0..1 preserves detail
    float edge_strength;    // 0..2 edge emphasis
    float quantization;     // 1..16 color levels
    float canvas_mix;       // 0..1 paper/canvas blend
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float luma(float3 c){ return dot(c, float3(0.2126,0.7152,0.0722)); }

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 texel = 1.0 / u.OutputSize.xy;

    // Adaptive kernel radius
    int r = int(clamp(u.brush_radius, 1.0, 8.0));

    // Compute local mean and bilateral-ish weighted average using simple range weight
    float3 mean = float3(0.0);
    float3 acc = float3(0.0);
    float wsum = 0.0;
    float3 center = src.sample(s, in.uv).rgb;

    float sigma_s = max(1.0, float(r)) * 0.5;
    float sigma_r = mix(0.2, 0.05, clamp(u.detail,0.0,1.0));
    float two_sigma_s2 = 2.0*sigma_s*sigma_s;
    float two_sigma_r2 = 2.0*sigma_r*sigma_r;

    for (int y=-r; y<=r; ++y) {
        for (int x=-r; x<=r; ++x) {
            float2 o = float2(x,y);
            float w_s = exp(-dot(o,o)/two_sigma_s2);
            float3 c = src.sample(s, in.uv + o*texel).rgb;
            float w_r = exp(-dot(c-center, c-center)/two_sigma_r2);
            float w = w_s * w_r;
            acc += c * w;
            mean += c;
            wsum += w;
        }
    }
    float3 smooth = (wsum>0.0) ? (acc/wsum) : center;

    // Edge emphasis using simple Sobel on luma
    float3 gx = float3(0.0); float3 gy = float3(0.0);
    float kx[9] = {-1,0,1,-2,0,2,-1,0,1};
    float ky[9] = {-1,-2,-1,0,0,0,1,2,1};
    int idx=0;
    for (int j=-1;j<=1;++j){
        for (int i=-1;i<=1;++i){
            float3 c = src.sample(s, in.uv + float2(i,j)*texel).rgb;
            float L = luma(c);
            gx += float3(L) * kx[idx];
            gy += float3(L) * ky[idx];
            idx++;
        }
    }
    float edge = clamp(length(float2(gx.r, gy.r)), 0.0, 1.0);

    // Color quantization to form paint bands
    float q = max(1.0, round(u.quantization));
    float3 quant = floor(smooth * q) / q;

    // Canvas/paper texture procedural
    float2 p = in.uv * u.OutputSize.xy;
    float noise = fract(sin(dot(p, float2(12.9898,78.233))) * 43758.5453 + float(u.FrameCount)*0.013);
    float paper = mix(0.96, 1.02, noise*noise);

    float3 color = quant;
    // Blend in edge emphasis
    color -= u.edge_strength * 0.2 * edge;
    // Canvas blend
    color *= mix(1.0, paper, clamp(u.canvas_mix,0.0,1.0));

    return float4(saturate(color), 1.0);
}

